CREATE POLICY "materials read own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'materials' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "materials insert own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'materials' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "materials update own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'materials' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'materials' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "materials delete own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'materials' AND (storage.foldername(name))[1] = auth.uid()::text);